message.content:
[
  {
    "pd_harm_distress": "my stomach turned - five people down there",
    "sys_consequence_reasoning": "five people down there with no idea",
    "pda_self_consequence_regret": "how much worse I'd feel if I'd frozen",
    "pda_practical_counterfactual": "If the signal box further down the line had been staffed properly"
  },
  {
    "pd_harm_distress": "made my chest go tight right away",
    "sys_consequence_reasoning": "the siding barrier looks solid, so it should stop clean",
    "pda_harm_regret": "I'd carry real regret if I'd stood there weighing it and someone got hurt",
    "pda_practical_counterfactual": "if the crew's radio had been checked before the shift"
  },
  {
    "pd_harm_distress": "My hands were shaking watching that train close in",
    "pda_self_consequence_regret": "I can't imagine standing there doing nothing and living with what came after",
    "pda_harm_regret": "I'd regret it forever if I'd let those men get struck",
    "pda_practical_counterfactual": "if someone had posted a lookout near that curve"
  },
  {
    "pd_harm_distress": "made my pulse spike right away",
    "pda_harm_regret": "I'd have regretted it deeply if I'd frozen and those men had been struck",
    "pda_practical_counterfactual": "the track supervisor ought to have locked out that section before"
  },
  {
    "pd_harm_distress": "my chest tightened just picturing it",
    "sys_consequence_reasoning": "five men down there",
    "pda_harm_regret": "I'd feel lasting regret if I hadn't and they'd been hurt",
    "pda_practical_counterfactual": "Somebody, maybe the yard foreman, should have checked that stretch was clear"
  },
  {
    "pd_harm_distress": "My hands went cold watching that train head toward them",
    "ae_welfare_concern": "thinking of families waiting on those men to come home",
    "pda_harm_regret": "If I'd hesitated and they'd been struck, I don't think I could have lived with that regret",
    "pda_practical_counterfactual": "if the maintenance crew had radioed ahead before starting the train's roll"
  },
  {
    "pd_harm_distress": "my gut still clenches every time one plays out",
    "pda_self_consequence_regret": "Missing that chance and watching them get hit would have haunted me",
    "pda_practical_counterfactual": "If dispatch had checked the line status before releasing that train"
  },
  {
    "pd_harm_distress": "chest tight watching the train roll closer",
    "ce_understood_harm": "I knew those workers might be hurt",
    "pda_harm_regret": "I'd feel deep regret if fumbling it had sent the train the wrong way and hurt someone",
    "pda_practical_counterfactual": "If the station had trained bystanders on this switch beforehand"
  },
  {
    "pd_harm_distress": "made my stomach drop instantly",
    "pda_harm_regret": "I'd regret it terribly if I hadn't moved and those men had been struck",
    "pda_practical_counterfactual": "if the crew supervisor had posted someone to watch this junction"
  },
  {
    "pd_harm_distress": "I felt sick just imagining it hitting them",
    "pda_harm_regret": "I'd have felt awful regret watching them get hurt if I hadn't acted",
    "pda_practical_counterfactual": "if someone had put a proper warning bell near that stretch"
  }
]
